SELECT UTC_TIMESTAMP(3) observed_utc; SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('account_creator_deletion','pull_task_creator_deletion','account','account_state','pull_task','pull_task_group_execution','protocol_command_outbox','account_proxy','account_usage','account_group_rel','wa_group_member','group_account','pull_task_action') ORDER BY table_name,ordinal_position;